import { prisma } from '@/lib/db'
import map from './legacy-redirects.json'

// 301s from the old altamoda.rs (CodeIgniter) URLs that Google still lists.
// The map is generated by scripts/build-legacy-redirects.py from the old DB dump.
//
//   /sr/proizvod/<uri>        → /products/<slug>   (by SKU, resolved here so slug changes don't break it)
//   /sr/proizvodi/<category>  → /products?category=…
//   /sr/brend/<brand>[/<n>]   → /brands/<slug>
//   /sr/pretraga?phrase=<q>   → /products?search=<q>
//   /sr/clanak/<article>      → /   (the new site has no blog)
//   /sr/<page>                → matching new page, else /
// The same applies under /en/.

type ProductTarget = { sku: string; fallback: string } | { path: string }

const products = map.products as Record<string, ProductTarget>
const categories = map.categories as Record<string, string>
const brands = map.brands as Record<string, string>
const pages = map.pages as Record<string, string>

async function productPath(uri: string): Promise<string> {
  const target = products[uri]
  if (!target) return '/products'
  if ('path' in target) return target.path
  const product = await prisma.product.findFirst({
    where: { sku: target.sku, isActive: true },
    select: { slug: true },
  })
  return product ? `/products/${product.slug}` : target.fallback
}

export async function resolveLegacyPath(segments: string[], searchParams: URLSearchParams): Promise<string> {
  const [section = '', slug = ''] = segments.map((s) => decodeURIComponent(s).toLowerCase())

  switch (section) {
    case 'proizvod':
    case 'product':
      return productPath(slug)
    case 'proizvodi':
    case 'products':
      return categories[slug] ?? '/products'
    case 'brend':
    case 'brand':
      return brands[slug] ?? '/brands'
    case 'pretraga':
    case 'search': {
      const phrase = searchParams.get('phrase')?.trim()
      return phrase ? `/products?search=${encodeURIComponent(phrase)}` : '/products'
    }
    case 'clanak':
    case 'article':
      return '/'
    default:
      return pages[section] ?? '/'
  }
}

export async function legacyRedirect(request: Request, segments: string[] | undefined): Promise<Response> {
  let location = '/'
  try {
    location = await resolveLegacyPath(segments ?? [], new URL(request.url).searchParams)
  } catch (err) {
    // A DB hiccup must not turn an old link into an error page.
    console.error('[legacy-redirect]', err)
    location = '/products'
  }
  // Relative Location: the app runs behind a proxy, so request.url's host is
  // not necessarily the public one.
  return new Response(null, {
    status: 301,
    headers: { Location: location, 'Cache-Control': 'public, max-age=86400' },
  })
}
